-- Create "polls" table
CREATE TABLE "polls" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "description" text NULL, "max_answers" bigint NOT NULL DEFAULT 1, "available_from" timestamptz NULL, "available_to" timestamptz NULL, "results_only" boolean NOT NULL DEFAULT false, "allow_revote" boolean NOT NULL DEFAULT true, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "polls_nodes_nodes" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "polls_nid" to table: "polls"
CREATE UNIQUE INDEX "polls_nid" ON "polls" ("nid");
-- Create "poll_options" table
CREATE TABLE "poll_options" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "label" character varying NOT NULL, "weight" bigint NOT NULL DEFAULT 0, "poll_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "poll_options_polls_options" FOREIGN KEY ("poll_id") REFERENCES "polls" ("id") ON DELETE CASCADE);
-- Create index "polloption_poll_id" to table: "poll_options"
CREATE INDEX "polloption_poll_id" ON "poll_options" ("poll_id");
-- Create "poll_votes" table
CREATE TABLE "poll_votes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "poll_id" bigint NOT NULL, "option_id" bigint NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "poll_votes_polls_votes" FOREIGN KEY ("poll_id") REFERENCES "polls" ("id") ON DELETE CASCADE, CONSTRAINT "poll_votes_poll_options_option_votes" FOREIGN KEY ("option_id") REFERENCES "poll_options" ("id") ON DELETE CASCADE, CONSTRAINT "poll_votes_users_poll_votes" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "pollvote_poll_id_user_id_option_id" to table: "poll_votes"
CREATE UNIQUE INDEX "pollvote_poll_id_user_id_option_id" ON "poll_votes" ("poll_id", "user_id", "option_id");
-- Create index "pollvote_poll_id_user_id" to table: "poll_votes"
CREATE INDEX "pollvote_poll_id_user_id" ON "poll_votes" ("poll_id", "user_id");
-- Create index "pollvote_option_id" to table: "poll_votes"
CREATE INDEX "pollvote_option_id" ON "poll_votes" ("option_id");
-- Create index "pollvote_user_id" to table: "poll_votes"
CREATE INDEX "pollvote_user_id" ON "poll_votes" ("user_id");
